expect={'and':lambda a,b:a and b,'or':lambda a,b:a or b,'implies':lambda a,b:(not a) or b,'not and':lambda a,b:not(a and b),'eq bool':lambda a,b:a,'ne bool':lambda a,b:not b}
for name,e in exprs.items():
 for a in [0,1]:
  for b in [0,1]:
   got=test(e,a,b); exp=expect[name](bool(a),bool(b))
   if got!=exp: print('BAD',name,a,b,got,exp)
print('done')
